#include <stdlib.h>

#define MAXN 200005
#define MAXE 800005

int parent[MAXN], sz[MAXN], degreeArr[MAXN];
int head[MAXN], to[MAXE], nxt[MAXE], markArr[MAXN];

int find(int x) {
    if (parent[x] != x)
        parent[x] = find(parent[x]);
    return parent[x];
}

void unite(int a, int b) {
    a = find(a);
    b = find(b);

    if (a == b) return;

    if (sz[a] < sz[b]) {
        int tmp = a;
        a = b;
        b = tmp;
    }

    parent[b] = a;
    sz[a] += sz[b];
}

