        degreeArr[x]++;
        degreeArr[y]++;

        to[edgeIndex] = y;
        nxt[edgeIndex] = head[x];
        head[x] = edgeIndex++;

        to[edgeIndex] = x;
        nxt[edgeIndex] = head[y];
        head[y] = edgeIndex++;

        unite(x, y);
    }

    int chosen = 0;
    int root = 0;

    for (int i = 1; i <= N; i++) {
        int r = find(i);

        if (sz[r] - 1 > degreeArr[i]) {
            chosen = i;
            root = r;
            break;
        }
    }

    if (chosen == 0) {
        printf("-1\n");
        return 0;
    }

    for (int e = head[chosen]; e != -1; e = nxt[e]) {
        markArr[to[e]] = 1;
    }

    for (int v = 1; v <= N; v++) {
        if (v == chosen) continue;
        if (markArr[v]) continue;

        if (find(v) == root) {
            printf("%d %d\n", chosen, v);
            return 0;
        }
    }

    printf("-1\n");
    return 0;
}
